import {createChatOrchestrator} from './chatOrchestrator.js';
import {createMockProvider} from '../providers/mock/mockProvider.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {ChatSession} from '../types/session.js';

it('reports a string rejection with its cause and preserves the caller value [specs/hal-engine-config-hooks/spec.md#8]', async () => {
  const errors: Error[] = [];
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const orchestrator = createChatOrchestrator(
    createMockProvider(),
    new PromptBuilder({identity: 'Assistant'}),
    undefined,
    {
      hooks: {
        beforeUserInput: async () => {
          throw 'string boom';
        },
        onError: async (_session, error) => {
          errors.push(error);
        },
      },
    }
  );

  const outcome = await orchestrator.processMessage(session).then(
    value => ({rejected: false, value}),
    (value: unknown) => ({rejected: true, value})
  );

  expect({outcome, errors: errors.map(error => ({isError: error instanceof Error, message: error.message, cause: error.cause}))}).toEqual({
    outcome: {rejected: true, value: 'string boom'},
    errors: [{isError: true, message: 'string boom', cause: 'string boom'}],
  });
});
EOF
 timeout 300 npm test -- --runTestsByPath src/orchestration/chatOrchestrator.rejection.test.ts --runInBand"
